class Queue:
    def __init__(self):
        self.items = []

    def enqueue(self, x):
        self.items.append(x)

    def dequeue(self):
        return self.items.pop(0)

    def size(self):
        return len(self.items)

setup:
def run_ops(obj, steps):
    out = []
    for step in steps:
        name, *args = step
        r = getattr(obj, name)(*args)
        if r is not None:
            out.append(r)
    return out
